int main() {
    int n, m;
    scanf("%d%d", &n, &m);

    for (int i = 0; i < n; ++i) {
        scanf("%d", &a[i]);
    }

    int groups = 0;
    int i = 0;

    while (i < n) {
        int sum = 0;

        do {
            if (sum > 0 && sum + a[i] > m) {
                break;
            }
            sum += a[i++];
        } while (i < n && sum < m);

        ++groups;
    }

    printf("%d", groups);
